// Verification reports are produced only by the CLI isolated-restore checker.
// Never read arbitrary user-supplied paths or expose the underlying backup SQL.
$verifiedReports=[];$reportsDir='C:/xampp/attendance-backups';
if(is_dir($reportsDir)){
 $reportPaths=glob($reportsDir.'/verification_*.json')?:[];
 usort($reportPaths,static fn($a,$b)=>filemtime($b)<=>filemtime($a));
 foreach(array_slice($reportPaths,0,20) as $reportPath){
  if(!is_file($reportPath)||filesize($reportPath)>65536)continue;
  $data=json_decode((string)file_get_contents($reportPath),true);
  if(!is_array($data)||!isset($data['checked_at_utc']))continue;
  $verifiedReports[]=['date'=>(string)$data['checked_at_utc'],'file'=>(string)($data['backup']??''),'restored'=>($data['restored_content_matches']??false)===true,'cleanup'=>($data['temporary_database_removed']??false)===true,'table_count'=>is_array($data['verified_row_counts']??null)?count($data['verified_row_counts']):0];
 }
}
?>
<section class="panel"><h2>Isolated restore verification</h2><p class="muted">Verification reports appear here after running <code>scripts/verify_backup_restore.ps1</code> on the office PC. This checks the backup in a temporary database and removes it. A generated backup alone is not a verified restore. Verify outside the live database.</p>
<div class="table-wrap"><table><thead><tr><th>Checked (UTC)</th><th>Backup</th><th>Restore comparison</th><th>Temporary DB cleanup</th><th>Tables checked</th></tr></thead><tbody>
